{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h2",
        "intro_text",
        "context_h3",
        "context_bedroom_def",
        "context_pet_friendly",
        "neighborhoods_h3",
        "prenzlauer_berg_card",
        "friedrichshain_card",
        "neukoelln_card",
        "wedding_card",
        "rental_terms_h3",
        "lease_term_stack",
        "notice_period_stack",
        "security_deposit_stack",
        "warm_cold_rent_stack",
        "pet_clause_stack",
        "proof_income_stack",
        "no_kitchen_stack",
        "quick_actions_h3",
        "quick_actions_stack",
        "sources_h3",
        "sources_stack"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Berlin Apartment Search: Neighborhood & Lease Guide",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Finding a 2-bedroom apartment in Berlin for €1800 (excluding utilities) that is pet-friendly and within a 30-minute public transport commute to Mitte is a realistic goal, though competition can be high. This guide outlines suitable neighborhoods and explains typical lease terms.",
        "variant": "body"
      },
      "children": []
    },
    "context_h3": {
      "type": "Text",
      "props": {
        "text": "Context for Your Search",
        "variant": "h3"
      },
      "children": []
    },
    "context_bedroom_def": {
      "type": "Text",
      "props": {
        "text": "2-Bedroom Definition: In Germany, a \"2-Zimmer-Wohnung\" typically means an apartment with two main habitable rooms (e.g., one living room and one bedroom), plus a separate kitchen and bathroom. A \"3-Zimmer-Wohnung\" would usually offer two separate bedrooms and a living room. For a \"2-bedroom\" request, we assume you are looking for either a 2-Zimmer or a compact 3-Zimmer apartment.",
        "variant": "body"
      },
      "children": []
    },
    "context_pet_friendly": {
      "type": "Text",
      "props": {
        "text": "Pet-Friendly: While specific landlord approval is always required, many apartments in Berlin are pet-friendly, especially for small dogs. It's crucial to explicitly mention your dog in applications.",
        "variant": "body"
      },
      "children": []
    },
    "neighborhoods_h3": {
      "type": "Text",
      "props": {
        "text": "Recommended Pet-Friendly Neighborhoods",
        "variant": "h3"
      },
      "children": []
    },
    "prenzlauer_berg_card": {
      "type": "Card",
      "props": {},
      "children": [
        "pb_header_stack",
        "pb_vibe",
        "pb_commute",
        "pb_budget",
        "pb_pet_friendly"
      ]
    },
    "pb_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "pb_icon",
        "pb_name"
      ]
    },
    "pb_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000374_01_1_house.svg"
      },
      "children": []
    },
    "pb_name": {
      "type": "Text",
      "props": {
        "text": "Prenzlauer Berg",
        "variant": "label"
      },
      "children": []
    },
    "pb_vibe": {
      "type": "Text",
      "props": {
        "text": "Vibe: Popular, family-friendly, charming Altbau (old building) architecture, numerous parks and cafes.",
        "variant": "body"
      },
      "children": []
    },
    "pb_commute": {
      "type": "Text",
      "props": {
        "text": "Commute to Mitte: Excellent, often 10-20 minutes by U-Bahn (U2, U8) or Tram (M1, M10).",
        "variant": "body"
      },
      "children": []
    },
    "pb_budget": {
      "type": "Text",
      "props": {
        "text": "Budget: Can be on the higher end, but €1800 for a 2-room apartment is achievable, especially in areas further from the absolute center.",
        "variant": "body"
      },
      "children": []
    },
    "pb_pet_friendly": {
      "type": "Text",
      "props": {
        "text": "Pet-Friendliness: Generally good, with many green spaces.",
        "variant": "body"
      },
      "children": []
    },
    "friedrichshain_card": {
      "type": "Card",
      "props": {},
      "children": [
        "fh_header_stack",
        "fh_vibe",
        "fh_commute",
        "fh_budget",
        "fh_pet_friendly"
      ]
    },
    "fh_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "fh_icon",
        "fh_name"
      ]
    },
    "fh_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000374_01_2_building.svg"
      },
      "children": []
    },
    "fh_name": {
      "type": "Text",
      "props": {
        "text": "Friedrichshain",
        "variant": "label"
      },
      "children": []
    },
    "fh_vibe": {
      "type": "Text",
      "props": {
        "text": "Vibe: Young, vibrant, creative, with a mix of historical buildings and modern developments. Known for its nightlife and the East Side Gallery.",
        "variant": "body"
      },
      "children": []
    },
    "fh_commute": {
      "type": "Text",
      "props": {
        "text": "Commute to Mitte: Very good, 15-25 minutes by S-Bahn or U-Bahn (U5).",
        "variant": "body"
      },
      "children": []
    },
    "fh_budget": {
      "type": "Text",
      "props": {
        "text": "Budget: More accessible than Prenzlauer Berg, making €1800 for a 2-bedroom quite feasible.",
        "variant": "body"
      },
      "children": []
    },
    "fh_pet_friendly": {
      "type": "Text",
      "props": {
        "text": "Pet-Friendliness: Common, with Volkspark Friedrichshain nearby.",
        "variant": "body"
      },
      "children": []
    },
    "neukoelln_card": {
      "type": "Card",
      "props": {},
      "children": [
        "nk_header_stack",
        "nk_vibe",
        "nk_commute",
        "nk_budget",
        "nk_pet_friendly"
      ]
    },
    "nk_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "nk_icon",
        "nk_name"
      ]
    },
    "nk_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000374_01_3_geo-alt.svg"
      },
      "children": []
    },
    "nk_name": {
      "type": "Text",
      "props": {
        "text": "Northern Neukölln (e.g., Reuterkiez, Schillerkiez)",
        "variant": "label"
      },
      "children": []
    },
    "nk_vibe": {
      "type": "Text",
      "props": {
        "text": "Vibe: Trendy, diverse, with a strong artistic and international community. Offers a lively atmosphere and unique independent shops.",
        "variant": "body"
      },
      "children": []
    },
    "nk_commute": {
      "type": "Text",
      "props": {
        "text": "Commute to Mitte: Good, 20-30 minutes by U-Bahn (U7, U8) or S-Bahn.",
        "variant": "body"
      },
      "children": []
    },
    "nk_budget": {
      "type": "Text",
      "props": {
        "text": "Budget: Generally more affordable than central districts, providing good options within your budget.",
        "variant": "body"
      },
      "children": []
    },
    "nk_pet_friendly": {
      "type": "Text",
      "props": {
        "text": "Pet-Friendliness: Increasingly common, with Tempelhofer Feld offering vast open space.",
        "variant": "body"
      },
      "children": []
    },
    "wedding_card": {
      "type": "Card",
      "props": {},
      "children": [
        "wd_header_stack",
        "wd_vibe",
        "wd_commute",
        "wd_budget",
        "wd_pet_friendly"
      ]
    },
    "wd_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "wd_icon",
        "wd_name"
      ]
    },
    "wd_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000374_01_4_map.svg"
      },
      "children": []
    },
    "wd_name": {
      "type": "Text",
      "props": {
        "text": "Wedding",
        "variant": "label"
      },
      "children": []
    },
    "wd_vibe": {
      "type": "Text",
      "props": {
        "text": "Vibe: Diverse, authentic, and rapidly developing. Offers a more local Berlin experience with growing cultural spots.",
        "variant": "body"
      },
      "children": []
    },
    "wd_commute": {
      "type": "Text",
      "props": {
        "text": "Commute to Mitte: Excellent, especially to northern Mitte, often 10-20 minutes by U-Bahn (U6, U9) or S-Bahn.",
        "variant": "body"
      },
      "children": []
    },
    "wd_budget": {
      "type": "Text",
      "props": {
        "text": "Budget: One of the most budget-friendly options for your requirements, offering good value.",
        "variant": "body"
      },
      "children": []
    },
    "wd_pet_friendly": {
      "type": "Text",
      "props": {
        "text": "Pet-Friendliness: Generally good, with several parks and green areas.",
        "variant": "body"
      },
      "children": []
    },
    "rental_terms_h3": {
      "type": "Text",
      "props": {
        "text": "Understanding Berlin Rental Terms",
        "variant": "h3"
      },
      "children": []
    },
    "lease_term_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "lease_term_label",
        "lease_term_body"
      ]
    },
    "lease_term_label": {
      "type": "Text",
      "props": {
        "text": "Lease Term (Mietvertrag)",
        "variant": "label"
      },
      "children": []
    },
    "lease_term_body": {
      "type": "Text",
      "props": {
        "text": "Most rental contracts in Germany are \"unbefristet\" (indefinite), meaning they don't have a fixed end date. They can only be terminated by either party with a legal notice period.",
        "variant": "body"
      },
      "children": []
    },
    "notice_period_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "notice_period_label",
        "notice_period_body"
      ]
    },
    "notice_period_label": {
      "type": "Text",
      "props": {
        "text": "Notice Period (Kündigungsfrist)",
        "variant": "label"
      },
      "children": []
    },
    "notice_period_body": {
      "type": "Text",
      "props": {
        "text": "For tenants, the standard notice period is three months, meaning you must give notice three months before you intend to move out. Landlords have stricter rules for termination.",
        "variant": "body"
      },
      "children": []
    },
    "security_deposit_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "security_deposit_label",
        "security_deposit_body"
      ]
    },
    "security_deposit_label": {
      "type": "Text",
      "props": {
        "text": "Security Deposit (Kaution)",
        "variant": "label"
      },
      "children": []
    },
    "security_deposit_body": {
      "type": "Text",
      "props": {
        "text": "Typically, the security deposit is up to three times the \"Nettokaltmiete\" (basic rent excluding utilities). This must be paid before moving in. It is held in a separate, interest-bearing account and returned after you move out, provided there are no damages.",
        "variant": "body"
      },
      "children": []
    },
    "warm_cold_rent_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "warm_cold_rent_label",
        "warm_cold_rent_body"
      ]
    },
    "warm_cold_rent_label": {
      "type": "Text",
      "props": {
        "text": "Warm Rent (Warmmiete) vs. Cold Rent (Kaltmiete)",
        "variant": "label"
      },
      "children": []
    },
    "warm_cold_rent_body": {
      "type": "Text",
      "props": {
        "text": "Kaltmiete: The basic rent for the apartment itself.\nNebenkosten (Utilities/Service Charges): These are additional monthly costs for things like heating, water, garbage collection, and building maintenance. Electricity and internet are usually separate contracts that you arrange directly with providers. Your €1800 budget excludes these.\nWarmmiete: Kaltmiete + Nebenkosten. This is the total amount you pay to the landlord monthly.",
        "variant": "body"
      },
      "children": []
    },
    "pet_clause_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "pet_clause_label",
        "pet_clause_body"
      ]
    },
    "pet_clause_label": {
      "type": "Text",
      "props": {
        "text": "Pet Clause (Tierhaltungsklausel)",
        "variant": "label"
      },
      "children": []
    },
    "pet_clause_body": {
      "type": "Text",
      "props": {
        "text": "The lease contract will specify rules regarding pets. It's common for small, harmless pets like dogs to be allowed with landlord permission. Always ensure this is explicitly stated or agreed upon in writing.",
        "variant": "body"
      },
      "children": []
    },
    "proof_income_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "proof_income_label",
        "proof_income_body"
      ]
    },
    "proof_income_label": {
      "type": "Text",
      "props": {
        "text": "Proof of Income (Einkommensnachweise)",
        "variant": "label"
      },
      "children": []
    },
    "proof_income_body": {
      "type": "Text",
      "props": {
        "text": "Landlords will typically request proof of income (e.g., last three payslips) and a Schufa-Auskunft (credit check).",
        "variant": "body"
      },
      "children": []
    },
    "no_kitchen_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "no_kitchen_label",
        "no_kitchen_body"
      ]
    },
    "no_kitchen_label": {
      "type": "Text",
      "props": {
        "text": "No Kitchen (Einbauküche)",
        "variant": "label"
      },
      "children": []
    },
    "no_kitchen_body": {
      "type": "Text",
      "props": {
        "text": "Many apartments in Germany are rented without a fitted kitchen (Einbauküche), meaning you would need to install your own. Some apartments do include one, often for an additional cost or a \"disposal fee\" from the previous tenant.",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "search_apartments_button",
        "bvg_info_button",
        "rental_law_button"
      ]
    },
    "search_apartments_button": {
      "type": "Button",
      "props": {
        "label": "Find Apartments on Immobilienscout24"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.immobilienscout24.de/"
          }
        }
      },
      "children": []
    },
    "bvg_info_button": {
      "type": "Button",
      "props": {
        "label": "Explore Berlin Public Transport (BVG)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bvg.de/en/"
          }
        }
      },
      "children": []
    },
    "rental_law_button": {
      "type": "Button",
      "props": {
        "label": "Understand German Rental Law (English)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.howtogermany.com/pages/renting-in-germany.html"
          }
        }
      },
      "children": []
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "immobilienscout_source",
        "bvg_source",
        "howtogermany_source"
      ]
    },
    "immobilienscout_source": {
      "type": "Text",
      "props": {
        "text": "Immobilienscout24 (Apartment search portal): https://www.immobilienscout24.de/",
        "variant": "body"
      },
      "children": []
    },
    "bvg_source": {
      "type": "Text",
      "props": {
        "text": "BVG (Berlin Public Transport): https://www.bvg.de/en/",
        "variant": "body"
      },
      "children": []
    },
    "howtogermany_source": {
      "type": "Text",
      "props": {
        "text": "How To Germany (Expat guide): https://www.howtogermany.com/",
        "variant": "body"
      },
      "children": []
    }
  }
}
